/// A scope maps column/table names to input column indexes, for lookups during
/// expression construction.
#[derive(Default)]
pub struct Scope {
    /// The currently visible columns.
    columns: Vec<Label>,
    /// Index of currently visible tables, by query name.
    tables: HashSet<String>,
    /// Index of fully qualified table.column names to column indexes.
    qualified: HashMap<(String, String), usize>,
    /// Index of unqualified column names to column indexes.
    unqualified: HashMap<String, Vec<usize>>,
    /// Index of aggregate and GROUP BY expressions to column indexes.
    aggregates: HashMap<ast::Expression, usize>,
    /// Hidden columns.
    hidden: HashSet<usize>,
}

